import java.util.*;

class Solution {
    public int[] asteroidCollision(int[] carts) {
        int[] st = new int[carts.length];
        int top = -1;
        for (int c : carts) {
            boolean alive = true;
            while (alive && c < 0 && top >= 0 && st[top] > 0) {
                if (st[top] < -c) top--;                       // right-mover destroyed, keep fighting
                else if (st[top] == -c) { top--; alive = false; } // both destroyed
                else alive = false;                             // c destroyed
            }
            if (alive) st[++top] = c;
        }
        return Arrays.copyOf(st, top + 1);
    }
}

