class Solution:
    def asteroidCollision(self, carts: List[int]) -> List[int]:
        st = []
        for c in carts:
            alive = True
            while alive and c < 0 and st and st[-1] > 0:
                if st[-1] < -c: st.pop()
                elif st[-1] == -c: st.pop(); alive = False
                else: alive = False
            if alive: st.append(c)
        return st

