function asteroidCollision(carts) {
  const st = [];
  for (const c of carts) {
    let alive = true;
    while (alive && c < 0 && st.length && st[st.length - 1] > 0) {
      const top = st[st.length - 1];
      if (top < -c) st.pop();
      else { if (top === -c) st.pop(); alive = false; }
    }
    if (alive) st.push(c);
  }
  return st;
}
